<script setup>
import {onMounted,ref,computed} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import ResourceGrants from '../components/ResourceGrants.vue'
import NotificationPreferences from '../components/NotificationPreferences.vue'
import EntraSettings from '../components/EntraSettings.vue'
import EventExportSettings from '../components/EventExportSettings.vue'
import SecurityAutomationSettings from '../components/SecurityAutomationSettings.vue'
import BulkAgentEnrollment from '../components/BulkAgentEnrollment.vue'
import AgentPollSettings from '../components/AgentPollSettings.vue'
import ProcessExclusions from '../components/ProcessExclusions.vue'
import WefSettings from '../components/WefSettings.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import DiscoverySettings from '../components/DiscoverySettings.vue'
import ClassifierSettings from '../components/ClassifierSettings.vue'
import {applyTheme,localTheme,normalizeTheme,setLocalTheme} from '../lib/theme.js'
import {api,session,download} from '../services/api.js'
const tab=ref('credentials'),credentials=ref([]),users=ref([]),invites=ref([]),teams=ref([]),nodeGroups=ref([]),audit=ref([]),agents=ref([]),nodes=ref([]),error=ref(''),message=ref(''),formOpen=ref(false),credentialForm=ref({name:'',type:'local',username:'',password:'',privateKey:'',passphrase:'',hostKeyFingerprint:'',port:22,community:'',securityLevel:'noAuthNoPriv',authProtocol:'sha',authKey:'',privProtocol:'aes',privKey:'',visibility:'private',priority:100}),userForm=ref({email:'',password:'',role:'auditor'}),inviteForm=ref({email:'',role:'auditor',teamId:''}),inviteResult=ref(null),teamName=ref(''),enrollNode=ref(''),token=ref(null)
const me=ref(null),totpSetup=ref(null),totpCode=ref(''),disablePassword=ref(''),disableCode=ref('')
const newEmail=ref('')
const currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref('')
const serverTheme=ref('system'),browserTheme=ref(localTheme())
const uploadingAvatar=ref(false)
const portalBrand=ref({companyName:'WinFire Secure',imageUrl:null}),portalBrandBusy=ref(false)
const mfaPromptSettings=ref({failureMode:'closed',failOpenMinutes:5}),mfaPromptApproval=ref(false),mfaPromptBusy=ref(false)
const trainingSettings=ref({newHostTrainingDays:30,progressiveLearning:{enabled:false,startDays:15,intervalHours:24}}),trainingSaving=ref(false)
const directorySettings=ref({url:'',baseDn:'',bindCredentialId:'',nodeCredentialId:null,actionCredentialId:null,enabled:false,syncIntervalMinutes:60,allowLdapFallback:false}),directoryBusy=ref(false),directoryResult=ref(null),directoryApproval=ref(false),approvedDirectory=ref({url:'',bindCredentialId:''})
const tlsSettings=ref({httpsEnabled:false,files:{},restartRequired:true}),tlsBusy=ref(false)
const observabilitySettings=ref({logRetentionDays:90,dnsRefreshHours:24,eventCompactHours:24,dynamicNodeGroupsIntervalMinutes:60,hideLoopbackEvents:true,ignoreLoopbackIngest:false}),observabilitySaving=ref(false),observabilityTab=ref('logs')
const serverSettings=ref({fqdn:'',effectiveFqdn:'',publicBaseUrl:'',effectivePublicBaseUrl:'',fqdnSource:'unset',publicBaseUrlSource:'request',localCidrs:[],environmentOverrides:{fqdn:false,publicBaseUrl:false}}),serverConfigTab=ref('server'),serverSaving=ref(false)
const accessTab=ref('grants')
const rpcFilters=ref([]),rpcForm=ref({nodeId:'',interfaceUuid:'',opnum:'',source:'Any',action:'block',audit:false,label:''}),rpcBusy=ref(false),rpcInventory=ref(null),confirmDialogOpen=ref(false),confirmDialogMessage=ref(''),confirmDialogAction=ref(null),confirmDialogBusy=ref(false)
const auditFilters=ref({q:'',action:'',entityType:'',actor:'',from:'',to:''}),auditPage=ref(1),auditPageSize=ref(100),auditTotal=ref(0),auditSortBy=ref('time'),auditSortDir=ref('desc'),auditLoading=ref(false)
const auditPages=computed(()=>Math.max(1,Math.ceil(auditTotal.value/auditPageSize.value)))
function auditQuery(extra={}){const params={page:auditPage.value,pageSize:auditPageSize.value,sortBy:auditSortBy.value,sortDir:auditSortDir.value,...auditFilters.value,...extra};for(const key of ['from','to'])if(params[key])params[key]=new Date(params[key]).toISOString();return new URLSearchParams(Object.entries(params).filter(([,value])=>value!==''&&value!==null)).toString()}
async function loadAudit(){auditLoading.value=true;try{const result=await api(`/audit/search?${auditQuery()}`);audit.value=result.items;auditTotal.value=result.total}catch(e){error.value=e.message}finally{auditLoading.value=false}}
function auditSearch(){auditPage.value=1;loadAudit()}
function auditSort(column){if(auditSortBy.value===column)auditSortDir.value=auditSortDir.value==='asc'?'desc':'asc';else{auditSortBy.value=column;auditSortDir.value=column==='time'?'desc':'asc'}auditSearch()}
function auditMove(page){if(page<1||page>auditPages.value)return;auditPage.value=page;loadAudit()}
async function exportAudit(format){try{await download(`/audit/search?${auditQuery({export:format})}`,`audit-trail.${format}`)}catch(e){error.value=e.message}}
const userToDelete=ref(null),deleteConfirmOpen=ref(false)
const credentialWindowOpen=ref(false),selectedCredential=ref(null),credentialTargetKind=ref('node'),credentialNodeId=ref(''),credentialGroupId=ref(''),credentialNewPassword=ref(''),credentialTestResult=ref(null),credentialBusy=ref(false)
const origin=location.origin
const isAdmin=computed(()=>['owner','admin'].includes(session.user?.role))
const fallbackApprovalRequired=computed(()=>directorySettings.value.allowLdapFallback&&(!directorySettings.value.ldapFallbackApprovedAt||directorySettings.value.url!==approvedDirectory.value.url||directorySettings.value.bindCredentialId!==approvedDirectory.value.bindCredentialId))
const canManageUser=user=>isAdmin.value&&user.id!==session.user?.id&&(user.role!=='owner'||session.user?.role==='owner')
const canManageCredential=credential=>!!credential?.canWrite
async function load(){try{const requests=[api('/credentials'),api('/teams'),api(`/audit/search?${auditQuery()}`),api('/agents'),api('/nodes'),api('/settings/training'),api('/node-groups')];if(isAdmin.value)requests.push(api('/settings/directory'),api('/settings/observability'),api('/users'),api('/invites'),api('/portal-branding'),api('/settings/mfa-prompt'),api('/rpc-filters'),api('/settings/tls'),api('/settings/server'));const result=await Promise.all(requests);[credentials.value,teams.value,,agents.value,nodes.value,trainingSettings.value,nodeGroups.value]=result;audit.value=result[2].items;auditTotal.value=result[2].total;if(isAdmin.value){directorySettings.value=result[7];approvedDirectory.value={url:result[7].url,bindCredentialId:result[7].bindCredentialId};observabilitySettings.value=result[8];users.value=result[9];invites.value=result[10];portalBrand.value=result[11];mfaPromptSettings.value=result[12];rpcFilters.value=result[13];tlsSettings.value=result[14];serverSettings.value={...serverSettings.value,fqdn:result[15].configuredFqdn||'',effectiveFqdn:result[15].fqdn||'',publicBaseUrl:result[15].configuredPublicBaseUrl||'',effectivePublicBaseUrl:result[15].publicBaseUrl||'',localCidrs:(result[15].localCidrs||[]).join('\n'),fqdnSource:result[15].fqdnSource,publicBaseUrlSource:result[15].publicBaseUrlSource,environmentOverrides:result[15].environmentOverrides}}error.value=''}catch(e){error.value=e.message}}
async function uploadTls(kind,event){const file=event.target.files?.[0];if(!file)return;tlsBusy.value=true;error.value='';try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read certificate'));reader.readAsDataURL(file)});await api(`/settings/tls/${kind}`,{method:'PUT',body:{base64:String(dataUrl).split(',')[1]}});tlsSettings.value=await api('/settings/tls');message.value='TLS material uploaded. Restart the control plane to activate it.'}catch(e){error.value=e.message}finally{tlsBusy.value=false;event.target.value=''}}
async function saveServerSettings(){serverSaving.value=true;error.value='';try{const result=await api('/settings/server',{method:'PATCH',body:{fqdn:serverSettings.value.fqdn,publicBaseUrl:serverSettings.value.publicBaseUrl,localCidrs:String(serverSettings.value.localCidrs||'').split(/[\n,]/).map(value=>value.trim()).filter(Boolean)}});serverSettings.value={...serverSettings.value,fqdn:result.configuredFqdn||'',effectiveFqdn:result.fqdn||'',publicBaseUrl:result.configuredPublicBaseUrl||'',effectivePublicBaseUrl:result.publicBaseUrl||'',localCidrs:(result.localCidrs||[]).join('\n'),fqdnSource:result.fqdnSource,publicBaseUrlSource:result.publicBaseUrlSource,environmentOverrides:result.environmentOverrides};message.value='Server settings saved'}catch(e){error.value=e.message}finally{serverSaving.value=false}}
async function saveObservability(){observabilitySaving.value=true;error.value='';try{observabilitySettings.value=await api('/settings/observability',{method:'PATCH',body:{logRetentionDays:Number(observabilitySettings.value.logRetentionDays),dnsRefreshHours:Number(observabilitySettings.value.dnsRefreshHours),eventCompactHours:Number(observabilitySettings.value.eventCompactHours),dynamicNodeGroupsIntervalMinutes:Number(observabilitySettings.value.dynamicNodeGroupsIntervalMinutes),hideLoopbackEvents:observabilitySettings.value.hideLoopbackEvents,ignoreLoopbackIngest:observabilitySettings.value.ignoreLoopbackIngest}});message.value='Logs, DNS, and dynamic group settings saved'}catch(e){error.value=e.message}finally{observabilitySaving.value=false}}
async function saveTraining(){trainingSaving.value=true;error.value='';try{const settings=trainingSettings.value;trainingSettings.value=await api('/settings/training',{method:'PATCH',body:{newHostTrainingDays:Number(settings.newHostTrainingDays),progressiveLearning:{enabled:settings.progressiveLearning.enabled,startDays:Number(settings.progressiveLearning.startDays),intervalHours:Number(settings.progressiveLearning.intervalHours)}}});message.value='New-host training settings saved'}catch(e){error.value=e.message}finally{trainingSaving.value=false}}
async function saveDirectory(silent=false){directoryBusy.value=true;error.value='';try{const settings=directorySettings.value;directorySettings.value=await api('/settings/directory',{method:'PATCH',body:{url:settings.url,baseDn:settings.baseDn,bindCredentialId:settings.bindCredentialId,nodeCredentialId:settings.nodeCredentialId||null,enabled:settings.enabled,syncIntervalMinutes:Number(settings.syncIntervalMinutes),allowLdapFallback:settings.allowLdapFallback,...(fallbackApprovalRequired.value?{ldapFallbackApproved:directoryApproval.value}:{})}});approvedDirectory.value={url:directorySettings.value.url,bindCredentialId:directorySettings.value.bindCredentialId};directoryApproval.value=false;if(!silent)message.value='Active Directory settings saved';return true}catch(e){error.value=e.message;return false}finally{directoryBusy.value=false}}
async function saveDirectoryActionCredential(){directoryBusy.value=true;error.value='';try{directorySettings.value=await api('/settings/directory/action-credential',{method:'PATCH',body:{credentialId:directorySettings.value.actionCredentialId||null}});message.value='AD account-control credential saved'}catch(e){error.value=e.message}finally{directoryBusy.value=false}}
async function testDirectory(){message.value='';if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/test',{method:'POST',body:{}});message.value=`Directory bind and search base validated over ${directoryResult.value.transport==='ldap'?'LDAP 389 (approved fallback)':'LDAPS'}`}catch(e){error.value=e.message}finally{directoryBusy.value=false}}
async function syncDirectoryNow(){message.value='';if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/sync',{method:'POST',body:{}});message.value=`Directory sync completed over ${directoryResult.value.transport==='ldap'?'LDAP 389 (approved fallback)':'LDAPS'}: ${directoryResult.value.created} added, ${directoryResult.value.updated} updated`;await load()}catch(e){await load();error.value=e.message}finally{directoryBusy.value=false}}
async function createCredential(){try{await api('/credentials',{method:'POST',body:credentialForm.value});formOpen.value=false;credentialForm.value={name:'',type:'local',username:'',password:'',privateKey:'',passphrase:'',hostKeyFingerprint:'',port:22,community:'',securityLevel:'noAuthNoPriv',authProtocol:'sha',authKey:'',privProtocol:'aes',privKey:'',visibility:'private',priority:100};await load()}catch(e){error.value=e.message}}
function openCredential(credential){selectedCredential.value=credential;credentialTargetKind.value='node';credentialNodeId.value='';credentialGroupId.value='';credentialNewPassword.value='';credentialTestResult.value=null;credentialWindowOpen.value=true}
async function assignCredential(){if(!selectedCredential.value)return;const body=credentialTargetKind.value==='node'?{nodeId:credentialNodeId.value}:{nodeGroupId:credentialGroupId.value};if(!Object.values(body)[0])return;credentialBusy.value=true;error.value='';try{const result=await api(`/credentials/${selectedCredential.value.id}/assignments`,{method:'POST',body});message.value=result.alreadyAssigned?'Credential already assigned':'Credential assigned to '+credentialTargetKind.value}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function testCredential(){if(!selectedCredential.value||!credentialNodeId.value)return;credentialBusy.value=true;error.value='';credentialTestResult.value=null;try{credentialTestResult.value=await api(`/credentials/${selectedCredential.value.id}/test`,{method:'POST',body:{nodeId:credentialNodeId.value}})}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function rotateCredential(){if(!selectedCredential.value||!credentialNewPassword.value)return;credentialBusy.value=true;error.value='';try{await api(`/credentials/${selectedCredential.value.id}`,{method:'PATCH',body:{password:credentialNewPassword.value}});credentialNewPassword.value='';message.value='Credential password rotated';await load()}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function createUser(){try{await api('/users',{method:'POST',body:userForm.value});userForm.value={email:'',password:'',role:'auditor'};message.value='User created';await load()}catch(e){error.value=e.message}}
async function createInvite(){try{inviteResult.value=await api('/invites',{method:'POST',body:{email:inviteForm.value.email,role:inviteForm.value.role,teamId:inviteForm.value.teamId||undefined}});inviteForm.value={email:'',role:'auditor',teamId:''};message.value=inviteResult.value.delivered?'Invitation emailed':'Invitation created; copy the link below';await load()}catch(e){error.value=e.message}}
async function revokeSessions(user){try{await api(`/users/${user.id}/revoke-sessions`,{method:'POST',body:{}});message.value=`Sessions revoked for ${user.email}`;await load()}catch(e){error.value=e.message}}
async function setSuspended(user){try{await api(`/users/${user.id}`,{method:'PATCH',body:{suspended:!user.suspended}});message.value=`${user.email} ${user.suspended?'restored':'suspended'}`;await load()}catch(e){error.value=e.message}}
async function deleteUser(){if(!userToDelete.value)return;const user=userToDelete.value;try{await api(`/users/${user.id}`,{method:'DELETE'});userToDelete.value=null;deleteConfirmOpen.value=false;message.value=`${user.email} deleted`;await load()}catch(e){error.value=e.message}}
function confirmDeleteUser(user){userToDelete.value=user;deleteConfirmOpen.value=true}
async function createTeam(){try{await api('/teams',{method:'POST',body:{name:teamName.value}});teamName.value='';await load()}catch(e){error.value=e.message}}
async function createToken(){try{token.value=await api('/agents/enrollment-tokens',{method:'POST',body:{nodeId:enrollNode.value}})}catch(e){error.value=e.message}}
async function revokeAgent(agent){try{await api(`/agents/${agent.id}/revoke`,{method:'POST',body:{}});message.value='Agent certificate revoked';await load()}catch(e){error.value=e.message}}
async function beginTotp(){try{totpSetup.value=await api('/auth/totp/setup',{method:'POST',body:{}});error.value=''}catch(e){error.value=e.message}}
async function confirmTotp(){try{await api('/auth/totp/confirm',{method:'POST',body:{code:totpCode.value}});me.value=await api('/auth/me');totpSetup.value=null;totpCode.value='';message.value='Authenticator enabled'}catch(e){error.value=e.message}}
async function removeTotp(){try{await api('/auth/totp/disable',{method:'POST',body:{password:disablePassword.value,code:disableCode.value}});me.value=await api('/auth/me');disablePassword.value='';disableCode.value='';message.value='Authenticator disabled'}catch(e){error.value=e.message}}
async function savePortalBrand(){portalBrandBusy.value=true;error.value='';try{portalBrand.value=await api('/settings/portal-branding',{method:'PATCH',body:{companyName:portalBrand.value.companyName}});message.value='Portal company name saved'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false}}
async function saveMfaPromptSettings(){mfaPromptBusy.value=true;error.value='';try{mfaPromptSettings.value=await api('/settings/mfa-prompt',{method:'PATCH',body:{failureMode:mfaPromptSettings.value.failureMode,failOpenMinutes:Number(mfaPromptSettings.value.failOpenMinutes),confirmed:mfaPromptApproval.value}});mfaPromptApproval.value=false;message.value='Automatic MFA prompt fallback saved'}catch(e){error.value=e.message}finally{mfaPromptBusy.value=false}}
async function createRpcFilter(){rpcBusy.value=true;error.value='';try{await api('/rpc-filters',{method:'POST',body:{...rpcForm.value,nodeId:rpcForm.value.nodeId,interfaceUuid:rpcForm.value.interfaceUuid,opnum:rpcForm.value.opnum===''?null:Number(rpcForm.value.opnum),source:rpcForm.value.source||'Any',audit:rpcForm.value.action==='allow'&&rpcForm.value.audit,label:rpcForm.value.label}});message.value='RPC filter staged';rpcForm.value={...rpcForm.value,interfaceUuid:'',opnum:'',source:'Any',label:''};await load()}catch(e){error.value=e.message}finally{rpcBusy.value=false}}
async function applyRpcFilter(filter){rpcBusy.value=true;error.value='';try{const result=await api(`/rpc-filters/${filter.id}/apply-inventory`,{method:'POST',body:{}});message.value=`Applied ${result.applied.length} RPC filter${result.applied.length===1?'':'s'} to ${filter.nodeHostname||'the node'}`;await load()}catch(e){error.value=e.message}finally{rpcBusy.value=false}}
async function inspectRpcFilters(filter){rpcBusy.value=true;error.value='';try{rpcInventory.value=await api(`/rpc-filters/${filter.id}/inventory`)}catch(e){error.value=e.message}finally{rpcBusy.value=false}}
function askConfirmation(message,action){confirmDialogMessage.value=message;confirmDialogAction.value=action;confirmDialogOpen.value=true}
async function runConfirmation(){const action=confirmDialogAction.value;confirmDialogOpen.value=false;confirmDialogAction.value=null;if(action){confirmDialogBusy.value=true;try{await action()}finally{confirmDialogBusy.value=false}}}
function deleteRpcFilter(filter){askConfirmation(`Remove the RPC filter “${filter.label||filter.interfaceUuid}”?`,async()=>{rpcBusy.value=true;error.value='';try{await api(`/rpc-filters/${filter.id}`,{method:'DELETE'});message.value='RPC filter removed';await load()}catch(e){error.value=e.message}finally{rpcBusy.value=false}})}
async function uploadPortalBrand(event){const file=event.target.files?.[0];if(!file)return;error.value='';if(file.size>1024*1024){error.value='Portal image must be under 1 MB';event.target.value='';return}portalBrandBusy.value=true;try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});portalBrand.value=await api('/settings/portal-branding/image',{method:'PUT',body:{mimeType:file.type,base64:String(dataUrl).split(',')[1]}});message.value='Portal image updated'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false;event.target.value=''}}
async function removePortalBrand(){portalBrandBusy.value=true;error.value='';try{portalBrand.value=await api('/settings/portal-branding/image',{method:'DELETE'});message.value='Portal image removed'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false}}
async function uploadAvatar(event){const file=event.target.files?.[0];if(!file)return;error.value='';if(file.size>512*1024){error.value='Avatar must be under 512 KB';return}uploadingAvatar.value=true;try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});await api(`/users/${session.user.id}/avatar`,{method:'PUT',body:{mimeType:file.type,base64:String(dataUrl).split(',')[1]}});me.value=await api('/auth/me');message.value='Avatar updated'}catch(e){error.value=e.message}finally{uploadingAvatar.value=false;event.target.value=''}}
async function changeEmail(){try{await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{email:newEmail.value}});message.value='Verification sent to the new address';newEmail.value=''}catch(e){error.value=e.message}}
async function changePassword(){error.value='';if(newPassword.value!==confirmPassword.value){error.value='New passwords do not match';return}try{await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{currentPassword:currentPassword.value,password:newPassword.value}});session.clear();location.assign('/login')}catch(e){error.value=e.message}}
async function saveTheme(){error.value='';try{const profile=await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{theme:serverTheme.value}});serverTheme.value=profile.theme;applyTheme(profile.theme);message.value='Account theme saved'}catch(e){error.value=e.message}}
function changeBrowserTheme(){setLocalTheme(browserTheme.value)}
async function resendVerification(){try{await api('/auth/email-verification/request',{method:'POST',body:{}});message.value='Verification sent to your current address'}catch(e){error.value=e.message}}
onMounted(async()=>{await load();me.value=await api('/auth/me');serverTheme.value=normalizeTheme(me.value.profile?.theme)||'system';browserTheme.value=localTheme();applyTheme(serverTheme.value)})
</script>
<template><div class="view"><PageHeader eyebrow="CONTROL PLANE / SETTINGS" title="Administration" description="Manage credentials, operators, teams and agent enrollment" /><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="admin-layout"><aside class="panel glass admin-nav"><button v-for="name in ['credentials','access','users','teams','agents','training','observability','notifications','directory','discovery','classifier','entra','serverConfig','rpcFilters','tls','audit','security']" :key="name" v-show="!['directory','observability','notifications','discovery','classifier','entra','serverConfig','rpcFilters','tls'].includes(name)||isAdmin" :class="{active:tab===name}" @click="tab=name"><i class="mdi" :class="`mdi-${({credentials:'key-outline',access:'share-variant-outline',users:'account-multiple-outline',teams:'account-group-outline',agents:'lan-connect',training:'brain',observability:'radar',directory:'domain',discovery:'radar',classifier:'tag-multiple-outline',notifications:'bell-outline',entra:'microsoft-azure',serverConfig:'server-outline',rpcFilters:'shield-lock-outline',tls:'certificate-outline',audit:'clipboard-text-clock-outline',security:'shield-key-outline'})[name]}`"></i>{{name==='rpcFilters'?'RPC filters':name==='classifier'?'Classifier':name==='notifications'?'Notifications':name==='serverConfig'?'Server config':name}}</button></aside><section class="panel glass admin-content"><template v-if="tab==='security'"><div class="panel-title"><div><span class="eyebrow">MY ACCOUNT</span><h2>Authenticator</h2></div><span class="status" :class="me?.totpEnabled?'reachable':'unknown'">{{me?.totpEnabled?'Enabled':'Disabled'}}</span></div><div class="security-settings"><p>Protect your control plane login with a 6-digit code from an authenticator app.</p><div class="avatar-setting"><img v-if="me?.profile?.avatar_url" :src="me.profile.avatar_url" alt="Your avatar" class="avatar-preview"><div v-else class="avatar-preview avatar-placeholder">{{session.user?.email?.[0]?.toUpperCase()||'W'}}</div><label>Profile image (PNG, JPEG or WebP, up to 512 KB)<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploadingAvatar" @change="uploadAvatar"></label></div><form class="inline-form" @submit.prevent="changeEmail"><input v-model="newEmail" type="email" required :placeholder="me?.email||'New email address'" aria-label="New email address"><button class="button small secondary">Change email</button></form><div class="appearance-setting"><h3>Appearance</h3><div class="appearance-controls"><label>Account theme<select v-model="serverTheme"><option value="system">System</option><option value="hacker">Hacker</option><option value="enterprise">Enterprise</option></select></label><button class="button small secondary" @click="saveTheme">Save account theme</button><label>This browser<select v-model="browserTheme" @change="changeBrowserTheme"><option value="system">Use account theme</option><option value="hacker">Hacker override</option><option value="enterprise">Enterprise override</option></select></label></div></div><form class="password-form" @submit.prevent="changePassword"><h3>Change password</h3><label>Current password<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" required></label><label>Confirm new password<input v-model="confirmPassword" type="password" autocomplete="new-password" minlength="12" required></label><button class="button small secondary">Change password</button></form><button v-if="me&&!me.emailVerified" class="button small secondary" @click="resendVerification">Resend email verification</button><template v-if="!me?.totpEnabled"><button v-if="!totpSetup" class="button primary" @click="beginTotp">Set up authenticator</button><div v-else class="form-grid"><label>Setup secret<input :value="totpSetup.secret" readonly></label><label>Authenticator URI<input :value="totpSetup.uri" readonly></label><label>Enter current code<input v-model="totpCode" inputmode="numeric" maxlength="6" placeholder="000000"></label><div class="form-actions"><button class="button primary" @click="confirmTotp">Verify and enable</button></div></div></template><div v-else class="form-grid"><label>Current password<input v-model="disablePassword" type="password"></label><label>Authenticator code<input v-model="disableCode" inputmode="numeric" maxlength="6"></label><div class="form-actions"><button class="button danger" @click="removeTotp">Disable authenticator</button></div></div></div></template><template v-else-if="tab==='training'"><div class="panel-title"><div><span class="eyebrow">HOST LIFECYCLE</span><h2>New host training</h2></div><span class="status learning">Automatic</span></div><div class="training-settings"><p>Each node gets a personal learned policy. Policy Studio previews observed rules during training. At the deadline, that policy and assigned group policies are applied and the learned rules stop changing automatically.</p><form class="training-settings-form" @submit.prevent="saveTraining"><label>Default training period (days)<input v-model.number="trainingSettings.newHostTrainingDays" type="number" min="1" max="365" required></label><label class="training-check"><input v-model="trainingSettings.progressiveLearning.enabled" type="checkbox"> Enable progressive learning</label><template v-if="trainingSettings.progressiveLearning.enabled"><label>First apply after (days)<input v-model.number="trainingSettings.progressiveLearning.startDays" type="number" min="1" :max="trainingSettings.newHostTrainingDays-1" required></label><label>Update interval (hours)<input v-model.number="trainingSettings.progressiveLearning.intervalHours" type="number" min="1" max="168" required></label></template><button v-if="isAdmin" class="button primary" :disabled="trainingSaving">{{trainingSaving?'Saving…':'Save training settings'}}</button></form><p class="muted">These defaults apply to new training sessions. Progressive updates create policy versions and stop at the session deadline. Existing deadlines and schedules are unchanged.</p></div></template><template v-else-if="tab==='observability'"><div class="panel-title"><div><span class="eyebrow">DATA LIFECYCLE</span><h2>Observability</h2></div></div><div class="admin-subtabs" role="tablist" aria-label="Observability settings"><button type="button" :class="{active:observabilityTab==='logs'}" @click="observabilityTab='logs'">Logs and DNS</button><button type="button" :class="{active:observabilityTab==='exclusions'}" @click="observabilityTab='exclusions'">Exclusions</button><button type="button" :class="{active:observabilityTab==='wef'}" @click="observabilityTab='wef'">WEF</button></div><template v-if="observabilityTab==='logs'"><div class="training-settings"><p>Choose how long security events stay in the database and how often the control plane refreshes each node's DNS records. Retention runs hourly; DNS refresh runs in batches every 15 minutes.</p><form class="training-settings-form" @submit.prevent="saveObservability"><label>Log retention (days)<input v-model.number="observabilitySettings.logRetentionDays" type="number" min="1" max="3650" required></label><label>DNS refresh interval (hours)<input v-model.number="observabilitySettings.dnsRefreshHours" type="number" min="1" max="720" required></label><label>Summarize event patterns every (hours)<input v-model.number="observabilitySettings.eventCompactHours" type="number" min="1" max="720" required></label><label>Dynamic node group refresh (minutes)<input v-model.number="observabilitySettings.dynamicNodeGroupsIntervalMinutes" type="number" min="5" max="10080" required></label><label class="training-check"><input v-model="observabilitySettings.hideLoopbackEvents" type="checkbox"> Hide local loopback traffic by default</label><label class="training-check"><input v-model="observabilitySettings.ignoreLoopbackIngest" type="checkbox"> Discard local loopback traffic on ingestion</label><button class="button primary" :disabled="observabilitySaving">{{observabilitySaving?'Saving…':'Save settings'}}</button></form></div></template><template v-else-if="observabilityTab==='exclusions'"><div class="training-settings"><div class="panel-title"><div><span class="eyebrow">DATA FILTERING</span><h2>Exclusions</h2></div></div><p>Manage global process and traffic ignore rules. Matching events are discarded before storage and hidden from Activities and search.</p><ProcessExclusions /></div></template><template v-else><div class="training-settings"><div class="panel-title"><div><span class="eyebrow">WINDOWS EVENT FORWARDING</span><h2>WEF</h2></div></div><WefSettings /></div></template></template><template v-else-if="tab==='notifications'"><div class="panel-title"><div><span class="eyebrow">CONTROL PLANE / ALERTING</span><h2>Notifications</h2></div></div><NotificationPreferences :me="me" /><SecurityAutomationSettings v-if="isAdmin" /><EventExportSettings v-if="isAdmin" /></template><template v-else-if="tab==='tls'"><div class="panel-title"><div><span class="eyebrow">CONTROL PLANE SECURITY</span><h2>TLS and agent certificates</h2></div><span class="status" :class="tlsSettings.httpsEnabled?'reachable':'unknown'">{{tlsSettings.httpsEnabled?'Configured':'Not configured'}}</span></div><div class="training-settings tls-settings"><p>Upload PEM encoded certificates and private keys for the control plane HTTPS listener and agent certificate authority. Files are stored with restricted permissions. Environment paths take precedence; a restart is required after every change.</p><div class="tls-material-grid"><label>Server certificate (.pem)<input type="file" accept=".pem,.crt,application/x-pem-file" :disabled="tlsBusy" @change="uploadTls('serverCert',$event)"><small>{{tlsSettings.files?.TLS_CERT?.configured?'Configured':'Missing'}} · {{tlsSettings.files?.TLS_CERT?.source}}</small></label><label>Server private key<input type="file" accept=".pem,.key,application/x-pem-file" :disabled="tlsBusy" @change="uploadTls('serverKey',$event)"><small>{{tlsSettings.files?.TLS_KEY?.configured?'Configured':'Missing'}} · {{tlsSettings.files?.TLS_KEY?.source}}</small></label><label>Agent CA certificate<input type="file" accept=".pem,.crt,application/x-pem-file" :disabled="tlsBusy" @change="uploadTls('agentCaCert',$event)"><small>{{tlsSettings.files?.AGENT_CA_CERT?.configured?'Configured':'Missing'}} · {{tlsSettings.files?.AGENT_CA_CERT?.source}}</small></label><label>Agent CA private key<input type="file" accept=".pem,.key,application/x-pem-file" :disabled="tlsBusy" @change="uploadTls('agentCaKey',$event)"><small>{{tlsSettings.files?.AGENT_CA_KEY?.configured?'Configured':'Missing'}} · {{tlsSettings.files?.AGENT_CA_KEY?.source}}</small></label></div><p class="hint">Use an encrypted private key in production and provide its passphrase through the deployment secret configuration. The control plane will not display or return private key contents.</p></div></template><template v-else-if="tab==='entra'"><EntraSettings /></template><template v-else-if="tab==='serverConfig'"><div class="panel-title"><div><span class="eyebrow">CONTROL PLANE / CONFIGURATION</span><h2>Server config</h2></div></div><div class="admin-subtabs" role="tablist" aria-label="Server configuration"><button type="button" :class="{active:serverConfigTab==='server'}" @click="serverConfigTab='server'">Server</button><button type="button" :class="{active:serverConfigTab==='branding'}" @click="serverConfigTab='branding'">Branding</button></div><template v-if="serverConfigTab==='server'"><div class="training-settings server-settings"><p>Set the control plane host identity used when an external base URL is not supplied by the deployment environment. Environment values take precedence over values saved here.</p><form class="form-grid" @submit.prevent="saveServerSettings"><label>Server FQDN<input v-model.trim="serverSettings.fqdn" maxlength="253" placeholder="winfire.example.com" :disabled="serverSettings.environmentOverrides.fqdn"></label><label>Public base URL<input v-model.trim="serverSettings.publicBaseUrl" type="url" maxlength="2048" placeholder="https://winfire.example.com" :disabled="serverSettings.environmentOverrides.publicBaseUrl"><small>Used for WEF callbacks, MFA links, and agent enrollment when PUBLIC_BASE_URL is not set.</small></label><label class="full-span">Local asset CIDRs<textarea v-model="serverSettings.localCidrs" rows="4" placeholder="192.168.88.0/24&#10;192.168.250.0/24"></textarea><small>Only addresses inside these IPv4 CIDRs appear in Monitored assets. External peers remain available in Firewall events and Mapping.</small></label><div class="server-config-status"><span>Effective FQDN: <strong>{{serverSettings.effectiveFqdn||'Request host'}}</strong> · {{serverSettings.fqdnSource}}</span><span>Effective URL: <strong>{{serverSettings.effectivePublicBaseUrl||'Request URL'}}</strong> · {{serverSettings.publicBaseUrlSource}}</span></div><div class="form-actions"><button class="button primary" :disabled="serverSaving||serverSettings.environmentOverrides.fqdn&&serverSettings.environmentOverrides.publicBaseUrl">{{serverSaving?'Saving…':'Save server settings'}}</button></div></form></div></template><template v-else><div class="panel-title"><div><span class="eyebrow">ACCESS PORTAL</span><h2>Company branding</h2></div></div><div class="branding-settings"><p>Show your company name and image on the MFA access page. The image is served from this control plane.</p><form class="form-grid" @submit.prevent="savePortalBrand"><label>Company name<input v-model.trim="portalBrand.companyName" maxlength="80" required></label><div class="form-actions"><button class="button primary" :disabled="portalBrandBusy">Save company name</button></div></form><div class="portal-brand-preview"><img v-if="portalBrand.imageUrl" :src="portalBrand.imageUrl" alt="MFA portal brand image"><span v-else>No custom image uploaded</span></div><label>Portal image (PNG, JPEG, or WebP, up to 1 MB)<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="portalBrandBusy" @change="uploadPortalBrand"></label><button v-if="portalBrand.imageUrl" class="button small secondary" :disabled="portalBrandBusy" @click="removePortalBrand">Remove image</button></div></template></template><template v-else-if="tab==='discovery'"><DiscoverySettings :credentials="credentials" /></template><template v-else-if="tab==='classifier'"><ClassifierSettings /></template><template v-else-if="tab==='directory'"><div class="panel-title"><div><span class="eyebrow">INVENTORY SOURCE</span><h2>Active Directory</h2></div><span class="status" :class="directorySettings.lastSyncStatus==='failed'?'unreachable':directorySettings.enabled?'reachable':'unknown'">{{directorySettings.lastSyncStatus==='failed'?'Needs attention':directorySettings.enabled?'Scheduled':'Disabled'}}</span></div><div class="directory-settings"><p>Use a read-only directory account from the credential vault to discover computer objects. LDAPS certificate validation is required. Discovered hosts enter new-host training when enabled in AD.</p><form class="directory-form" @submit.prevent="saveDirectory()"><label>LDAPS server URL<input v-model.trim="directorySettings.url" type="url" required placeholder="ldaps://dc.example.com:636/"></label><label>Search base DN<input v-model.trim="directorySettings.baseDn" required placeholder="DC=example,DC=com"></label><label>Directory bind credential<select v-model="directorySettings.bindCredentialId" required><option value="">Select vault credential</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.username}}</option></select></label><label>WinRM credential for discovered nodes<select v-model="directorySettings.nodeCredentialId"><option :value="null">Assign later</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><label>Sync interval (minutes)<input v-model.number="directorySettings.syncIntervalMinutes" type="number" min="5" max="1440" required></label><label class="directory-toggle"><input v-model="directorySettings.enabled" type="checkbox"> Enable scheduled inventory sync</label><div class="directory-fallback-control"><label class="directory-fallback-toggle"><input v-model="directorySettings.allowLdapFallback" type="checkbox"> Allow LDAP 389 fallback when LDAPS cannot connect</label><p>Administrator approval is required. LDAP 389 simple bind sends the directory credential without TLS. Use a dedicated read-only account on a trusted network. Certificate validation failures will never trigger fallback.</p><label v-if="fallbackApprovalRequired" class="directory-fallback-toggle confirm-checkbox"><input v-model="directoryApproval" type="checkbox"> I approve LDAP 389 fallback for this server and bind credential.</label><small v-else-if="directorySettings.allowLdapFallback">Approved {{directorySettings.ldapFallbackApprovedAt?new Date(directorySettings.ldapFallbackApprovedAt).toLocaleString():''}}</small></div><div class="directory-actions"><button class="button primary" :disabled="directoryBusy">Save connection</button><button type="button" class="button secondary" :disabled="directoryBusy" @click="testDirectory">Test connection</button><button type="button" class="button secondary" :disabled="directoryBusy||!directorySettings.enabled" @click="syncDirectoryNow">Sync computers now</button></div></form><div class="directory-action-credential"><h3>AD account controls</h3><p>Use a separate delegated credential for account enable/disable. Changes require certificate-validated LDAPS and are audited. Temporary disables are re-enabled only if the AD flags still match WinFire's change.</p><label>Account-control credential<select v-model="directorySettings.actionCredentialId"><option :value="null">Disabled</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.username}}</option></select></label><button class="button small secondary" :disabled="directoryBusy" @click="saveDirectoryActionCredential">Save account-control credential</button></div><div class="directory-status"><strong>Last sync: {{directorySettings.lastSyncStatus||'Never'}}</strong><span>{{directorySettings.lastSyncedAt?new Date(directorySettings.lastSyncedAt).toLocaleString():'No successful sync yet'}} · {{directorySettings.lastSyncCount??0}} computers</span><small v-if="directorySettings.lastTransport">Last successful transport: {{directorySettings.lastTransport==='ldap'?'LDAP 389 approved fallback':'LDAPS'}}</small><small v-if="directorySettings.lastSyncError" class="danger-text">{{directorySettings.lastSyncError}}</small><small v-if="directoryResult?.found!==undefined">Latest run: {{directoryResult.created}} added, {{directoryResult.updated}} updated, {{directoryResult.missing}} missing from AD.</small></div><p class="muted">Directory sync never deletes a node or its policies. Trust the domain controller certificate with the server OS or NODE_EXTRA_CA_CERTS. Account control actions require separate review and are not enabled here.</p></div></template><template v-else-if="tab==='access'"><div class="panel-title"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Access</h2></div></div><div class="admin-subtabs" role="tablist" aria-label="Access settings"><button type="button" role="tab" :aria-selected="accessTab==='grants'" :class="{active:accessTab==='grants'}" @click="accessTab='grants'">Resource grants</button><button type="button" role="tab" :aria-selected="accessTab==='mfaFallback'" :class="{active:accessTab==='mfaFallback'}" @click="accessTab='mfaFallback'">Automatic MFA prompt</button></div><ResourceGrants v-if="accessTab==='grants'" /><div v-else class="mfa-fallback-settings"><div class="panel-title"><div><span class="eyebrow">CLIENT CONTROL</span><h3>Automatic MFA prompt fallback</h3></div></div><p>When a blocked connection comes from a client outside AD inventory, or a known client cannot be reached or authenticated over WinRM, choose how the target responds. Fail open creates a short, source IP scoped firewall grant without MFA. Every grant is audited and expires automatically.</p><form class="form-grid" @submit.prevent="saveMfaPromptSettings"><label>Client control failure<select v-model="mfaPromptSettings.failureMode"><option value="closed">Fail closed (recommended)</option><option value="open">Fail open temporarily</option></select></label><label v-if="mfaPromptSettings.failureMode==='open'">Fallback grant duration (minutes)<input v-model.number="mfaPromptSettings.failOpenMinutes" type="number" min="2" max="15" required></label><label v-if="mfaPromptSettings.failureMode==='open'" class="check-label confirm-checkbox"><input v-model="mfaPromptApproval" type="checkbox"> I understand fail-open can allow temporary access without MFA when the client cannot be controlled.</label><div class="form-actions"><button class="button primary" :disabled="mfaPromptBusy">Save fallback setting</button></div></form><p class="muted">A client with no matching outbound event or no identifiable active process session remains blocked. Disconnected sessions are never prompted.</p></div></template><template v-else-if="tab==='credentials'"><div class="panel-title"><div><span class="eyebrow">SECRET STORE</span><h2>Credential vault</h2></div><button class="button small primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> Add credential</button></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>TYPE</th><th>USERNAME</th><th>VISIBILITY</th><th>PRIORITY</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="credential in credentials" :key="credential.id"><td><i class="mdi mdi-key-outline"></i> {{credential.name}}</td><td>{{credential.type}}</td><td class="mono">{{credential.username}}</td><td>{{credential.visibility}}</td><td>{{credential.priority}}</td><td><button class="button small secondary" @click="openCredential(credential)">Manage</button></td></tr><tr v-if="!credentials.length"><td colspan="6" class="empty-table">No credentials stored. Add one before connecting to a node.</td></tr></tbody></table></div></template><template v-else-if="tab==='users'"><div class="panel-title"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Operators</h2></div></div><div class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>STATUS</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.email}}</td><td>{{user.role}}</td><td><span class="status" :class="user.suspended?'unreachable':'reachable'">{{user.suspended?'Suspended':'Active'}}</span></td><td>{{new Date(user.created_at).toLocaleDateString()}}</td><td><div v-if="canManageUser(user)" class="user-actions"><button class="button small secondary" @click="revokeSessions(user)">Revoke sessions</button><button class="button small secondary" @click="setSuspended(user)">{{user.suspended?'Restore':'Suspend'}}</button><button v-if="session.user?.role==='owner'" class="button small danger" @click="confirmDeleteUser(user)">Delete</button></div></td></tr></tbody></table></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createUser"><input v-model="userForm.email" type="email" required placeholder="New user's email"><input v-model="userForm.password" type="password" minlength="12" required placeholder="Temporary password"><select v-model="userForm.role" aria-label="New user role"><option>auditor</option><option>editor</option><option>admin</option></select><button class="button small primary">Create user</button></form><div v-if="isAdmin" class="panel-title"><div><span class="eyebrow">ONBOARDING</span><h2>Invitations</h2></div></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createInvite"><input v-model="inviteForm.email" type="email" required placeholder="Invitee email"><select v-model="inviteForm.role" aria-label="Invite role"><option>auditor</option><option>editor</option><option>admin</option><option v-if="session.user?.role==='owner'">owner</option></select><select v-model="inviteForm.teamId" aria-label="Invite team"><option value="">No team</option><option v-for="team in teams" :key="team.id" :value="team.id">{{team.name}}</option></select><button class="button small primary">Invite</button></form><div v-if="inviteResult?.inviteUrl" class="code-block">{{inviteResult.inviteUrl.startsWith('http')?inviteResult.inviteUrl:origin+inviteResult.inviteUrl}}<small>Share this link with {{inviteResult.email}}. It expires in seven days.</small></div><div v-if="invites.length" class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>DELIVERY</th><th>STATUS</th></tr></thead><tbody><tr v-for="invite in invites" :key="invite.id"><td>{{invite.email}}</td><td>{{invite.role}}</td><td>{{invite.delivered_at?'Emailed':'Manual link'}}</td><td>{{invite.accepted_at?'Accepted':new Date(invite.expires_at)<new Date()?'Expired':'Pending'}}</td></tr></tbody></table></div></template><template v-else-if="tab==='teams'"><div class="panel-title"><div><span class="eyebrow">ORGANIZATION</span><h2>Teams</h2></div></div><div v-for="team in teams" :key="team.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-account-group-outline"></i></div><strong>{{team.name}}</strong></div><div v-if="!teams.length" class="empty-side">No teams created.</div><form v-if="isAdmin" class="inline-form" @submit.prevent="createTeam"><input v-model="teamName" required placeholder="New team name"><button class="button small primary">Create team</button></form></template><template v-else-if="tab==='agents'"><div class="panel-title"><div><span class="eyebrow">ENDPOINT CONNECTIVITY</span><h2>Agents</h2></div></div><div v-for="agent in agents" :key="agent.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-lan-connect"></i></div><div><strong>{{nodes.find(n=>n.id===agent.node_id)?.hostname||agent.node_id}}</strong><small>{{agent.version}} · {{agent.mode}} · {{agent.last_checkin_at||'Never checked in'}} · {{agent.revoked_at?'Revoked':'Active'}}</small></div><button v-if="isAdmin&&!agent.revoked_at" class="button small danger" @click="revokeAgent(agent)">Revoke</button></div><div v-if="!agents.length" class="empty-side">No agents enrolled.</div><div v-if="isAdmin" class="inline-form"><select v-model="enrollNode" aria-label="Node for agent token"><option value="">Select node for token</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select><button class="button small secondary" :disabled="!enrollNode" @click="createToken">Generate token</button></div><div v-if="token" class="code-block">{{token.token}}<small>Expires {{new Date(token.expiresAt).toLocaleString()}}</small></div><BulkAgentEnrollment v-if="isAdmin" :nodes="nodes" :agents="agents" /><AgentPollSettings v-if="isAdmin" :nodes="nodes" :groups="nodeGroups" /><p class="muted">Agent enrollment requires HTTPS and configured PKI. A signed MSI package is still in development.</p></template><template v-else-if="tab==='rpcFilters'"><div class="panel-title"><div><span class="eyebrow">NETWORK HARDENING</span><h2>RPC filters</h2></div><span class="count-chip">{{rpcFilters.length}}</span></div><p class="muted">Stage native Windows RPC filters for DCSync, WMI, PsExec, PetitPotam and ZeroLogon interfaces. Rules are kept in the control plane until an administrator applies the complete node set. Applying a block filter can interrupt administration; verify the interface and source before deployment.</p><form class="form-grid" @submit.prevent="createRpcFilter"><label>Target node<select v-model="rpcForm.nodeId" required><option value="">Select node</option><option v-for="node in nodes.filter(item=>item.connection_mode==='agentless')" :key="node.id" :value="node.id">{{node.hostname}} · {{node.status}}</option></select></label><label>Interface UUID<input v-model.trim="rpcForm.interfaceUuid" required placeholder="e3514235-4b06-11d1-ab04-00c04fc2dcd2"></label><label>Operation number (optional)<input v-model.trim="rpcForm.opnum" type="number" min="0" max="65535" placeholder="3"></label><label>Remote source IP/CIDR<input v-model.trim="rpcForm.source" placeholder="Any or 10.0.0.0/8"></label><label>Action<select v-model="rpcForm.action"><option value="block">Block</option><option value="allow">Permit</option><option value="continue">Continue</option></select></label><label v-if="rpcForm.action==='allow'" class="check-label"><input v-model="rpcForm.audit" type="checkbox"> Audit permitted calls (event 5712)</label><label>Label<input v-model.trim="rpcForm.label" maxlength="160" placeholder="Block DCSync from untrusted sources"></label><div class="form-actions"><button class="button primary" :disabled="rpcBusy">{{rpcBusy?'Saving…':'Stage RPC filter'}}</button></div></form><div class="table-wrap"><table><thead><tr><th>NODE</th><th>INTERFACE</th><th>OPNUM</th><th>SOURCE</th><th>ACTION</th><th>AUDIT</th><th>STATE</th><th aria-label="Actions"><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="filter in rpcFilters" :key="filter.id"><td>{{filter.nodeHostname||filter.node_id}}</td><td class="mono">{{filter.interfaceUuid}}</td><td>{{filter.opnum??'Any'}}</td><td class="mono">{{filter.source||'Any'}}</td><td><span class="status" :class="filter.action==='block'?'failed':'reachable'">{{filter.action}}</span></td><td>{{filter.audit?'yes':'no'}}</td><td>{{filter.appliedAt?'Applied':'Staged'}}</td><td><div class="inline-actions"><button class="button small secondary" :disabled="rpcBusy||filter.nodeStatus!=='reachable'" @click="inspectRpcFilters(filter)">Inspect host</button><button class="button small primary" :disabled="rpcBusy||!!filter.appliedAt||filter.nodeStatus!=='reachable'" @click="applyRpcFilter(filter)">Apply node set</button><button class="button small danger" :disabled="rpcBusy" @click="deleteRpcFilter(filter)">Remove</button></div></td></tr><tr v-if="!rpcFilters.length"><td colspan="8" class="empty-table">No RPC filters staged.</td></tr></tbody></table></div><pre v-if="rpcInventory" class="code-block">{{rpcInventory.raw}}</pre></template><template v-else><div class="panel-title"><div><span class="eyebrow">CHANGE HISTORY</span><h2>Audit trail</h2></div><span class="count-chip">{{auditTotal}} entries</span></div><form class="audit-controls" @submit.prevent="auditSearch"><input v-model.trim="auditFilters.q" placeholder="Search action, entity or actor" aria-label="Search audit trail"><input v-model.trim="auditFilters.action" placeholder="Action" aria-label="Filter action"><input v-model.trim="auditFilters.entityType" placeholder="Entity type" aria-label="Filter entity type"><input v-model.trim="auditFilters.actor" placeholder="Actor" aria-label="Filter actor"><label>From<input v-model="auditFilters.from" type="datetime-local"></label><label>To<input v-model="auditFilters.to" type="datetime-local"></label><button class="button small primary" :disabled="auditLoading">Search</button><label>Rows<select v-model.number="auditPageSize" @change="auditSearch"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option><option :value="250">250</option></select></label><button type="button" class="button small secondary" @click="exportAudit('csv')">CSV</button><button type="button" class="button small secondary" @click="exportAudit('pdf')">PDF</button><button type="button" class="button small secondary" @click="exportAudit('xls')">XLS</button></form><div class="table-wrap"><table><thead><tr><th><button class="audit-sort" @click="auditSort('time')">TIME ↕</button></th><th><button class="audit-sort" @click="auditSort('action')">ACTION ↕</button></th><th><button class="audit-sort" @click="auditSort('entity')">ENTITY ↕</button></th><th><button class="audit-sort" @click="auditSort('actor')">ACTOR ↕</button></th></tr></thead><tbody><tr v-for="entry in audit" :key="entry.id"><td>{{new Date(entry.at).toLocaleString()}}</td><td class="mono">{{entry.action}}</td><td>{{entry.entity_type}} / {{entry.entity_id?.slice(0,8)}}</td><td class="mono">{{entry.actor_email||'system'}}</td></tr><tr v-if="!audit.length"><td colspan="4" class="empty-table">{{auditLoading?'Loading…':'No audited actions match these filters.'}}</td></tr></tbody></table></div><div class="audit-pagination"><span>Page {{auditPage}} of {{auditPages}} · {{auditTotal}} entries</span><div><button class="button small secondary" :disabled="auditPage<=1||auditLoading" @click="auditMove(auditPage-1)">Previous</button><button class="button small secondary" :disabled="auditPage>=auditPages||auditLoading" @click="auditMove(auditPage+1)">Next</button></div></div></template></section></div><GlassWindow v-model="formOpen" title="Add credential"><form class="form-grid" @submit.prevent="createCredential"><label>Name<input v-model="credentialForm.name" required placeholder="Domain service account"></label><label>Type<select v-model="credentialForm.type"><option value="local">Local</option><option value="domain">Domain</option><option value="esxi">VMware ESXi</option><option value="ssh">Linux / SSH</option><option value="snmp-v2c">SNMP v2c</option><option value="snmp-v3">SNMP v3</option></select></label><label v-if="credentialForm.type!=='snmp-v2c'">Username<input v-model="credentialForm.username" :required="credentialForm.type!=='snmp-v2c'" :placeholder="credentialForm.type==='snmp-v3'?'snmp-user':credentialForm.type==='esxi'?'root':'DOMAIN\\service'"></label><label v-if="credentialForm.type==='snmp-v2c'">Community string<input v-model="credentialForm.community" required type="password" autocomplete="new-password"></label><template v-if="credentialForm.type==='snmp-v3'"><label>Security level<select v-model="credentialForm.securityLevel"><option value="noAuthNoPriv">No auth / no privacy</option><option value="authNoPriv">Auth / no privacy</option><option value="authPriv">Auth / privacy</option></select></label><label v-if="credentialForm.securityLevel!=='noAuthNoPriv'">Auth protocol<select v-model="credentialForm.authProtocol"><option>sha</option><option>sha256</option><option>sha512</option><option>md5</option></select></label><label v-if="credentialForm.securityLevel!=='noAuthNoPriv'">Auth key<input v-model="credentialForm.authKey" type="password" minlength="8" required autocomplete="new-password"></label><label v-if="credentialForm.securityLevel==='authPriv'">Privacy protocol<select v-model="credentialForm.privProtocol"><option>aes</option><option>aes256b</option><option>aes256r</option><option>des</option></select></label><label v-if="credentialForm.securityLevel==='authPriv'">Privacy key<input v-model="credentialForm.privKey" type="password" minlength="8" required autocomplete="new-password"></label></template><template v-if="credentialForm.type==='ssh'"><label>SSH password (optional)<input v-model="credentialForm.password" type="password" autocomplete="new-password"></label><label>Private key (optional)<textarea v-model="credentialForm.privateKey" rows="4" placeholder="-----BEGIN OPENSSH PRIVATE KEY-----"></textarea></label><label>Private key passphrase<input v-model="credentialForm.passphrase" type="password" autocomplete="new-password"></label><label>SSH port<input v-model.number="credentialForm.port" type="number" min="1" max="65535"></label><label>Host key SHA256 fingerprint (optional)<input v-model.trim="credentialForm.hostKeyFingerprint" placeholder="SHA256:…"></label></template><label v-if="credentialForm.type==='local'||credentialForm.type==='domain'||credentialForm.type==='esxi'">Password<input v-model="credentialForm.password" type="password" required autocomplete="new-password"></label><label>Visibility<select v-model="credentialForm.visibility"><option value="private">Private</option><option value="team">Team</option></select></label><label>Priority<input v-model.number="credentialForm.priority" type="number"></label><div class="form-actions"><button class="button primary">Store credential</button></div></form></GlassWindow><GlassWindow v-model="credentialWindowOpen" :title="`Manage ${selectedCredential?.name||'credential'}`" width="560px"><div class="credential-management"><p>Use this vault entry on a Windows, Linux/SSH, ESXi, or SNMP device/node group. The secret remains write-only.</p><div class="form-grid"><label>Target type<select v-model="credentialTargetKind"><option value="node">Node</option><option value="group">Node group</option></select></label><label v-if="credentialTargetKind==='node'">Node<select v-model="credentialNodeId" @change="credentialTestResult=null"><option value="">Select node</option><option v-for="node in nodes.filter(item=>item.connection_mode==='agentless')" :key="node.id" :value="node.id">{{node.hostname}}</option></select></label><label v-else>Node group<select v-model="credentialGroupId"><option value="">Select group</option><option v-for="group in nodeGroups" :key="group.id" :value="group.id">{{group.name}}</option></select></label></div><div class="inline-actions"><button class="button small secondary" :disabled="credentialBusy||!(credentialTargetKind==='node'?credentialNodeId:credentialGroupId)" @click="assignCredential">Assign credential</button><button v-if="credentialTargetKind==='node'" class="button small secondary" :disabled="credentialBusy||!credentialNodeId" @click="testCredential">Test authentication</button></div><p v-if="credentialTestResult" :class="credentialTestResult.success?'success-msg':'error-msg'">{{credentialTestResult.success?`${credentialTestResult.transport==='ssh'?'SSH':credentialTestResult.transport==='wmi'?'WMI/DCOM':'WinRM'} authenticated as ${credentialTestResult.account}${credentialTestResult.computerName?` on ${credentialTestResult.computerName}`:''}`:credentialTestResult.error}}</p><form v-if="canManageCredential(selectedCredential)" class="credential-rotate" @submit.prevent="rotateCredential"><h3>Rotate password</h3><label>New password<input v-model="credentialNewPassword" type="password" autocomplete="new-password" required></label><button class="button small primary" :disabled="credentialBusy">Rotate password</button></form></div></GlassWindow><GlassWindow v-model="deleteConfirmOpen" title="Delete operator" width="480px"><p>Delete {{userToDelete?.email}} and revoke their access permanently?</p><div class="form-actions"><button class="button secondary" @click="deleteConfirmOpen=false">Cancel</button><button class="button danger" @click="deleteUser">Delete operator</button></div></GlassWindow><ConfirmDialog v-model="confirmDialogOpen" :message="confirmDialogMessage" :busy="confirmDialogBusy" @confirm="runConfirmation" /></div></template>
